#to test different error forms
def calc_best_pop(popcalc):

    res = brute(
    popcalc.get_error_test,
    ((10_000, 800_000),),
    Ns=50,
    full_output=False,
    workers=5
    )

    popcalc.best_pop = float(res)
    popcalc.min_error = popcalc.get_error_test(res)
    print(f'best pop: {popcalc.best_pop}, error: {popcalc.min_error}')
    return 

